INSERT INTO capital_source_profiles (institution_id,capital_types,sectors,geographies,minimum_readiness,instrument_notes,eligibility_notes,evidence_urls) SELECT ip.id,'["debt","blended_finance"]'::jsonb,'["infrastructure","ict_telecoms","transportation","waste_management","water","renewable_energy","power","agriculture","social_infrastructure","gas_distribution"]'::jsonb,'["Nigeria"]'::jsonb,75,'Local-currency guarantees can enhance qualifying debt instruments and help attract pension funds, insurers and other long-term investors.','The route is infrastructure-focused and requires a viable, creditworthy transaction that satisfies current eligibility and underwriting criteria; it is not a direct grant or ordinary project loan.','["https://infracredit.ng/about-us/","https://infracredit.ng/our-guarantee/","https://infracredit.ng/our-products/our-financial-guarantee/"]'::jsonb FROM institutional_profiles ip WHERE ip.organization_name='InfraCredit' AND NOT EXISTS (SELECT 1 FROM capital_source_profiles csp WHERE csp.institution_id=ip.id);